    allc=[x for row in g for x in row]
    objs=[]; seeds=[]
    for col in set(allc):
        if col==8: continue
        for cc in comps(g,col):
            (objs if len(cc)>1 else seeds).append((col,cc))
    # only single-cell seeds
    for scol,S in [(c,ss) for c,ss in seeds if len(ss)==1]:
        sr,sc=S[0]
        best=None
        for ocol,O in objs:
            if ocol==scol: continue
            C=min(O,key=lambda p:(abs(p[0]-sr)+abs(p[1]-sc)))
            d=abs(C[0]-sr)+abs(C[1]-sc)
            if d<=1 and (best is None or d<best[0]):
                best=(d,C)
        if best is None: continue
        dm,(cr,cc_)=best
        if dm==1:
            # adjacent edge: mirror object across the perpendicular bisector line/point between seed and that cell
            if abs(cr-sr)==1:  # above/below -> horizontal axis y = midpoint
                axy=(sr+cr)/2; axis='h'
                P={(int(2*axy-r),c) for r,c in O}
            elif abs(cc_-sc)==1:  # left/right -> vertical axis
                axy=(sc+cc_) /2; axis='v'
                P={(r,int(2*axy-c)) for r,c in O}
            else:
                continue
        else:
            continue
        for r,c in P:
            if 0<=r<H and 0<=c<W and o[r][c]==8: o[r][c]=scol
    return o
